/* Webseiten gestalten – acht eigenständige Lektionen. */
(function(root){
"use strict";
root.SDAkademieKurse=root.SDAkademieKurse||Object.create(null);
root.SDAkademieKurse["webdesign"]=[{"id":"p2-1","title":"Selektoren und Klassen","minutes":25,"ziel":"Mit CSS gezielt ein Element gestalten.","schritte":[{"titel":"Klassen im HTML vergeben","text":"Eine Klasse ist wie ein Namensschild an einem Kleidungsstück. Du kannst mehreren Elementen dasselbe Schild geben. Im HTML steht dafür class. Im CSS beginnt der Klassenname mit einem Punkt. Eine Klasse verhält sich wie ein gemeinsames Etikett an mehreren Ordnern.","code":"<p class=\"hinweis\">Bitte anmelden.</p>","erklaerung":"Die erste Zeile ist ein Absatz mit der Klasse hinweis.","tiefer":["CSS steht für Cascading Style Sheets. Eine CSS-Regel besteht aus einem Selektor, der bestimmt, welche Elemente gemeint sind, und einem Deklarationsblock in geschweiften Klammern mit Eigenschaft und Wert, etwa `color: red;`. Der Browser liest das HTML, baut daraus einen Baum von Elementen und wendet dann alle passenden Regeln an.","Ein Element darf mehrere Klassen gleichzeitig tragen, getrennt durch Leerzeichen: `class=\"hinweis wichtig\"`. So kombinierst du Bausteine, etwa eine Grundgestaltung und eine Farbvariante. Klassennamen sollten beschreiben, was etwas ist (`hinweis`), nicht wie es aussieht (`rot`), damit sie auch nach einer Farbänderung noch passen."]},{"titel":"CSS-Klassenselektor schreiben","text":"Mit einem Punkt vor hinweis sprichst du nur passende Elemente an. Andere Absätze bleiben unverändert. Das ist nützlich für Warnungen oder Hinweise. Du kannst dieselbe Klasse mehrfach verwenden. So kannst du einen Hinweis später an einer einzigen CSS-Stelle verändern.","code":".hinweis { color: darkblue; }","erklaerung":"Der Punkt kennzeichnet den Klassenselektor.","tiefer":["Wenn mehrere Regeln dasselbe Element betreffen, entscheidet die Spezifität: ID-Selektoren wiegen am meisten, dann Klassen, dann einfache Elementnamen wie `p`. Bei gleicher Spezifität gewinnt die Regel, die weiter unten steht. Das ist das „Cascading“ – die Kaskade – im Namen CSS.","Selektoren lassen sich kombinieren: `article .hinweis` trifft nur Hinweise innerhalb eines Artikels, `p.hinweis` nur Absätze mit dieser Klasse. Mit `:hover` reagierst du auf die Maus, mit `:focus` auf die Tastatur. Die Entwicklerwerkzeuge des Browsers (F12) zeigen dir für jedes Element, welche Regeln gelten und welche überschrieben wurden."]},{"titel":"ID und Klasse unterscheiden","text":"Eine ID wird dagegen mit einer Raute ausgewählt. Sie sollte auf einer Seite nur einmal vorkommen. Klassen eignen sich für wiederkehrende Elemente. Prüfe die Schreibweise auf beiden Seiten. Prüfe die ID-Auswahl zunächst an einer einzelnen Überschrift.","code":"#kopf { background: lightgray; }","erklaerung":"Die Raute wählt das Element mit id=\"kopf\".","tiefer":["Eine ID muss auf einer Seite eindeutig sein, weil sie auch für Sprungmarken (`href=\"#kontakt\"`), Formularbeschriftungen und JavaScript benutzt wird. Doppelte IDs führen zu schwer erklärbaren Fehlern. Für Gestaltung sind Klassen deshalb fast immer die bessere Wahl.","Weil eine ID-Regel sehr spezifisch ist, lässt sie sich später nur mit noch spezifischeren Regeln überschreiben. Große Projekte vermeiden deshalb ID-Selektoren im CSS ganz. Groß- und Kleinschreibung zählt: `#Kontakt` und `#kontakt` sind verschiedene IDs."]},{"titel":"Zwei Hinweise gleich gestalten","text":"Ändere zuerst eine Klasse und beobachte die Vorschau. Danach gib einem zweiten Absatz dieselbe Klasse. Beide sollen die gleiche Farbe erhalten. So erkennst du den Vorteil gemeinsamer Regeln. Achte darauf, dass beide Absätze denselben Klassennamen tragen.","code":"<p class=\"hinweis\">Öffnungszeiten beachten.</p>","erklaerung":"Der zweite Absatz erhält dieselbe Gestaltung.","tiefer":["Wiederverwendbare Klassen sind die Grundlage jedes Designsystems. Statt jede Stelle einzeln zu gestalten, legst du einmal fest, wie ein Hinweis aussieht, und vergibst die Klasse überall. Änderst du die Farbe, ändern sich alle Hinweise auf einmal.","Viele Teams benennen Klassen nach festen Regeln, zum Beispiel nach BEM (Block, Element, Modifier): `karte`, `karte__titel`, `karte--hervorgehoben`. Solche Konventionen machen großen Code verständlich, weil man am Namen erkennt, wozu eine Klasse gehört."]}],"beispiel":{"html":"<p class=\"hinweis\">Hallo</p>","css":"","js":""},"aufgabe":{"text":"Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.","pruefungen":[{"beschreibung":"Die passende HTML-Struktur ist vorhanden.","test":"p2-class-html"},{"beschreibung":"Die passende Gestaltung oder Beschriftung ist vorhanden.","test":"p2-class-css"}],"tipp":"Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.","loesung":{"html":"<p class=\"hinweis\">Hallo</p>\n<p class=\"hinweis\">Willkommen</p>","css":".hinweis { color: darkblue; }","js":""}},"fehler":[{"titel":"Der Punkt vor einer Klasse fehlt","text":"Fehlt der Punkt vor dem Selektor, bleibt der Hinweis ohne gewünschte Farbe. Richtig ist `.hinweis { color: darkblue; }`, nicht `hinweis { color: darkblue; }`."},{"titel":"class und CSS-Name stimmen nicht überein","text":"Wenn im HTML `class=\"hinweis\"` steht, aber CSS `.hinweise` auswählt, bleibt der Absatz unverändert. Verwende auf beiden Seiten denselben Namen: `<p class=\"hinweis\">Text</p>` und `.hinweis { color: darkblue; }`."}],"quiz":[{"frage":"Welcher Selektor wählt class=\"info\"?","antworten":["info",".info","#info"],"richtig":1,"erklaerung":"Bei „Welcher Selektor wählt class=\"info\"?“ ist „.info“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Welche Aussage stimmt für Klassen?","antworten":["Eine Klasse darf nur einmal vorkommen.","Klassen ersetzen HTML.","Mehrere Elemente dürfen dieselbe Klasse haben."],"richtig":2,"erklaerung":"Für diese Aufgabe passt „Mehrere Elemente dürfen dieselbe Klasse haben.“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe."]},{"frage":"Wie wählst du id=\"kopf\"?","antworten":["#kopf",".kopf","kopf"],"richtig":0,"erklaerung":"Die Auswahl „#kopf“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.","begruendungen":["Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]}],"merke":["Ein Klassenname steht im HTML hinter `class` und im CSS hinter einem Punkt.","Mehrere Elemente können dieselbe Klasse tragen und dadurch gemeinsame Regeln nutzen."]},{"id":"p2-2","title":"Das Box-Modell verstehen","minutes":25,"ziel":"Innenabstand, Rahmen und Außenabstand unterscheiden.","schritte":[{"titel":"Innenabstand am Paket erklären","text":"Stell dir ein Paket im Karton vor. Der Inhalt ist dein Text. Das Polster entspricht padding. Die Kartonwand ist der border. Der Platz zum nächsten Karton ist margin. Ein Innenabstand macht den Text auch auf einem schmalen Display angenehmer lesbar.","code":".karte { padding: 16px; }","erklaerung":"padding schafft Platz zwischen Text und Kartenrand.","tiefer":["Jedes HTML-Element ist für den Browser ein Rechteck aus vier Schichten: Inhalt, Innenabstand (padding), Rahmen (border) und Außenabstand (margin). Dieses Box-Modell ist die Grundlage jedes Layouts. Die Entwicklerwerkzeuge zeigen die vier Schichten farbig an, wenn du ein Element auswählst.","padding nimmt die Hintergrundfarbe des Elements an, margin ist immer durchsichtig. Du kannst die Werte einzeln setzen (`padding-top`) oder als Kurzform: `padding: 10px 20px;` bedeutet oben und unten 10, links und rechts 20 Pixel. Bei vier Werten gilt die Reihenfolge oben, rechts, unten, links – im Uhrzeigersinn."]},{"titel":"Den sichtbaren Rahmen setzen","text":"Ein Rahmen macht die Kante sichtbar. Mit border kannst du Breite, Art und Farbe angeben. Ein Rahmen von zwei Pixeln bleibt sichtbar. Er umgibt den Innenabstand. Mit einer sichtbaren Linie erkennst du die Grenzen der Karte leichter.","code":".karte { border: 2px solid gray; }","erklaerung":"Die Regel zeichnet einen grauen Rahmen.","tiefer":["Die Kurzform `border: 2px solid #333;` setzt Breite, Linienart und Farbe auf einmal. Weitere Linienarten sind `dashed` (gestrichelt) und `dotted` (gepunktet). Mit `border-radius` rundest du die Ecken ab; `border-radius: 50%` macht aus einem Quadrat einen Kreis.","Ein Rahmen nimmt Platz ein und vergrößert das Element, wenn nicht border-box gilt. Willst du nur zur Fehlersuche sehen, wo ein Element liegt, nimm `outline`: Die Umrandung wird gezeichnet, verändert aber das Layout nicht."]},{"titel":"Außenabstand zu Nachbarn","text":"margin liegt außerhalb des Rahmens. Es trennt die Karte von Nachbarn. Du kannst oben und unten verschiedene Abstände setzen. Verwechsle es nicht mit padding. Zwischen zwei Karten sorgt der Außenabstand für eine klare Trennung.","code":".karte { margin: 12px 0; }","erklaerung":"Die erste Zahl betrifft oben und unten.","tiefer":["Vertikale Außenabstände benachbarter Elemente fallen zusammen: Hat eine Karte unten 20 Pixel und die nächste oben 30 Pixel margin, beträgt der Abstand 30, nicht 50 Pixel. Dieses Verhalten heißt Margin Collapsing und überrascht viele Anfänger. In Flexbox- und Grid-Layouts tritt es nicht auf.","Mit `margin: 0 auto;` zentrierst du ein Element mit fester Breite waagerecht, weil der Browser den freien Platz links und rechts gleich verteilt. In modernen Layouts ersetzt die Eigenschaft `gap` oft einzelne Außenabstände, weil sie nur zwischen Elementen wirkt und nicht am Rand."]},{"titel":"Breite mit border-box berechnen","text":"Die Gesamtbreite kann sonst überraschend groß werden. box-sizing: border-box rechnet padding und border in die eingestellte Breite ein. Das hilft bei kleinen Bildschirmen. Teste es mit einer Karte. Prüfe die Kartenbreite im Browser, wenn du padding erhöhst.","code":".karte { box-sizing: border-box; width: 100%; }","erklaerung":"Die Karte bleibt innerhalb ihres Containers.","tiefer":["Ohne Angabe gilt `box-sizing: content-box`: Die eingestellte Breite betrifft nur den Inhalt. Eine Karte mit `width: 300px`, 20 Pixel padding auf jeder Seite und 2 Pixel Rahmen ist dann in Wirklichkeit 344 Pixel breit. Mit border-box bleibt sie genau 300 Pixel breit.","Darum beginnen viele Stylesheets mit der Regel `*, *::before, *::after { box-sizing: border-box; }`. Sie gilt dann für alle Elemente der Seite. Das macht Breitenberechnungen vorhersehbar und verhindert, dass Inhalte auf schmalen Bildschirmen über den Rand ragen."]}],"beispiel":{"html":"<div class=\"karte\">Kontakt</div>","css":"","js":""},"aufgabe":{"text":"Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.","pruefungen":[{"beschreibung":"Die passende HTML-Struktur ist vorhanden.","test":"p2-padding-html"},{"beschreibung":"Die passende Gestaltung oder Beschriftung ist vorhanden.","test":"p2-padding-css"}],"tipp":"Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.","loesung":{"html":"<div class=\"karte\">Kontakt</div>","css":".karte {\n  padding: 16px;\n  margin: 12px;\n  border: 2px solid gray;\n  box-sizing: border-box;\n}","js":""}},"fehler":[{"titel":"margin mit padding verwechselt","text":"Wenn der Text direkt am Rahmen klebt, fehlt Innenabstand. Schreibe `.karte { padding: 16px; }` statt nur `margin: 16px`, denn margin liegt außerhalb der Karte."},{"titel":"border ohne Linienart geschrieben","text":"Wenn keine Umrandung erscheint, wurde oft die Linienart ausgelassen. Vollständig lautet die Regel `.karte { border: 2px solid gray; }`; `border: 2px gray` reicht nicht."}],"quiz":[{"frage":"Was schafft Abstand innerhalb des Rahmens?","antworten":["margin","padding","gap"],"richtig":1,"erklaerung":"Bei „Was schafft Abstand innerhalb des Rahmens?“ ist „padding“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was liegt außerhalb des Rahmens?","antworten":["margin","border","padding"],"richtig":0,"erklaerung":"Für diese Aufgabe passt „margin“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.","begruendungen":["Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Welche Einstellung erleichtert feste Breiten?","antworten":["display: none","font-style: italic","box-sizing: border-box"],"richtig":2,"erklaerung":"Die Auswahl „box-sizing: border-box“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe."]}],"merke":["padding liegt innerhalb, margin außerhalb der Rahmenlinie.","Mit `box-sizing: border-box` bleiben Rahmen und Innenabstand in der festgelegten Breite."]},{"id":"p2-3","title":"Flexbox für eine Navigation","minutes":25,"ziel":"Elemente nebeneinander und untereinander anordnen.","schritte":[{"titel":"Navigation als Flex-Container","text":"Eine Reihe von Stühlen lässt sich nebeneinander stellen. Flexbox ordnet HTML-Elemente ähnlich an. Die Einstellung kommt auf den gemeinsamen Container. Seine direkten Kinder werden flexibel angeordnet. Die Navigation ist der gemeinsame Behälter für ihre Links.","code":"nav { display: flex; }","erklaerung":"display: flex aktiviert die flexible Reihe.","tiefer":["Mit `display: flex` wird ein Element zum Flex-Container, seine direkten Kinder werden zu Flex-Elementen. Standardmäßig stehen sie dann nebeneinander in einer Zeile. Enkel-Elemente sind davon nicht betroffen – für sie bräuchtest du einen eigenen Flex-Container.","Flexbox ist ein eindimensionales Layoutsystem: Es ordnet Elemente entlang einer Achse an, entweder als Zeile (`flex-direction: row`) oder als Spalte (`column`). Für Navigationen, Werkzeugleisten und das Ausrichten von Elementen innerhalb einer Karte ist es die erste Wahl."]},{"titel":"Abstände zwischen Links","text":"Mit gap bestimmst du den Abstand zwischen den Einträgen. Du brauchst dann nicht für jeden Link einen eigenen Außenabstand. Das macht die Navigation übersichtlich. Der Abstand gilt gleichmäßig. Der Zwischenraum soll auch bei einem längeren Linknamen erhalten bleiben.","code":"nav { gap: 12px; }","erklaerung":"gap trennt die Links um zwölf Pixel.","tiefer":["`gap` wirkt nur zwischen den Elementen, nicht vor dem ersten und nach dem letzten. Bei margin entstünden dagegen zusätzliche Abstände am Rand, die man mühsam wieder entfernen müsste. Mit `gap: 10px 20px` setzt du Zeilen- und Spaltenabstand getrennt.","Damit Links gut antippbar sind, sollten sie nicht zu klein sein; Richtlinien für Barrierefreiheit empfehlen Tippflächen von mindestens etwa 24 mal 24 Pixeln, besser 44 Pixel. Gib Links dafür etwas padding. Der Abstand durch gap verhindert zusätzlich, dass man versehentlich den Nachbarn trifft."]},{"titel":"Elemente auf der Hauptachse","text":"justify-content steuert die Verteilung in der Hauptachse. Mit space-between entstehen Abstände zwischen den Einträgen. align-items richtet Elemente quer dazu aus. Beide Eigenschaften erfüllen verschiedene Aufgaben. Vergleiche die Verteilung links und rechts im breiten Fenster.","code":"nav { justify-content: space-between; }","erklaerung":"Die Links verteilen sich über die Breite.","tiefer":["Die Hauptachse folgt der Richtung von `flex-direction`, die Querachse steht senkrecht dazu. `justify-content` verteilt entlang der Hauptachse (`flex-start`, `center`, `space-between`, `space-around`), `align-items` richtet entlang der Querachse aus (`stretch`, `center`, `flex-start`).","Mit `flex-direction: column` tauschen die Achsen ihre Rollen: Dann verteilt `justify-content` senkrecht. Das verwirrt anfangs, ist aber logisch. Ein klassischer Trick: `display: flex; justify-content: center; align-items: center;` zentriert ein Element in beide Richtungen."]},{"titel":"Umbruch bei wenig Platz","text":"Auf schmalen Geräten passt eine lange Reihe nicht immer. flex-wrap erlaubt den Umbruch in eine weitere Zeile. So bleiben Links erreichbar. Probiere verschiedene Fensterbreiten aus. Bei 320 Pixeln sollten alle Navigationspunkte erreichbar bleiben.","code":"nav { flex-wrap: wrap; }","erklaerung":"Einträge dürfen in die nächste Zeile wechseln.","tiefer":["Ohne `flex-wrap: wrap` versucht Flexbox, alle Elemente in eine Zeile zu quetschen; sie werden schmaler oder ragen über den Rand. Mit wrap entstehen bei Bedarf weitere Zeilen. So bleibt die Navigation auch auf kleinen Bildschirmen vollständig.","Mit der Eigenschaft `flex` steuerst du, wie Elemente wachsen und schrumpfen: `flex: 1` lässt ein Element den freien Platz füllen. Für sehr viele Menüpunkte auf dem Handy nutzt man oft ein ausklappbares Menü; die Grundlage bleibt aber eine sauber umbrechende Liste."]}],"beispiel":{"html":"<nav><a href=\"#a\">Start</a><a href=\"#b\">Kontakt</a></nav>","css":"","js":""},"aufgabe":{"text":"Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.","pruefungen":[{"beschreibung":"Die passende HTML-Struktur ist vorhanden.","test":"p2-flex-html"},{"beschreibung":"Die passende Gestaltung oder Beschriftung ist vorhanden.","test":"p2-flex-css"}],"tipp":"Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.","loesung":{"html":"<nav><a href=\"#a\">Start</a><a href=\"#b\">Kontakt</a></nav>","css":"nav {\n  display: flex;\n  gap: 12px;\n  flex-wrap: wrap;\n}","js":""}},"fehler":[{"titel":"display: flex auf den Links statt dem Container","text":"Stehen die Links trotz `display: flex` untereinander, wurde die Regel möglicherweise auf einzelne Links statt auf `nav` gesetzt. Nutze `nav { display: flex; }` für ihren gemeinsamen Container."},{"titel":"flex-wrap vergessen und Links abgeschnitten","text":"Wenn die Navigation rechts aus dem Handybildschirm ragt, dürfen die Einträge nicht umbrechen. Ergänze `nav { display: flex; flex-wrap: wrap; gap: 12px; }` und prüfe die schmale Ansicht."}],"quiz":[{"frage":"Welche Eigenschaft aktiviert Flexbox?","antworten":["display: flex","position: flex","float: flex"],"richtig":0,"erklaerung":"Bei „Welche Eigenschaft aktiviert Flexbox?“ ist „display: flex“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.","begruendungen":["Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was erzeugt Abstand zwischen Flex-Kindern?","antworten":["color","gap","font-size"],"richtig":1,"erklaerung":"Für diese Aufgabe passt „gap“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was erlaubt den Zeilenumbruch?","antworten":["overflow: hidden","white-space: nowrap","flex-wrap: wrap"],"richtig":2,"erklaerung":"Die Auswahl „flex-wrap: wrap“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe."]}],"merke":["Flexbox wird auf dem gemeinsamen Eltern-Element eingeschaltet.","`flex-wrap: wrap` erlaubt bei Platzmangel eine weitere Zeile."]},{"id":"p2-4","title":"Grid für Seitenbereiche","minutes":25,"ziel":"Eine Seite in Spalten und Zeilen aufteilen.","schritte":[{"titel":"Ein Raster aktivieren","text":"Ein Kalender hat Spalten und Zeilen. CSS Grid nutzt dieselbe Idee für Webseiten. Du aktivierst Grid auf einem Container. Danach verteilst du die Kinder in ein Raster. Das Raster ähnelt einem Regal mit mehreren Fächern.","code":"main { display: grid; }","erklaerung":"Grid wird für alle direkten Kinder aktiviert.","tiefer":["Grid ist ein zweidimensionales Layoutsystem: Es ordnet Elemente gleichzeitig in Zeilen und Spalten an. Damit eignet es sich für ganze Seitenbereiche, Bildergalerien und Kartenraster. Flexbox und Grid ergänzen sich: Grid für das große Gerüst, Flexbox für die Ausrichtung im Kleinen.","Wie bei Flexbox wirkt `display: grid` nur auf die direkten Kinder. Ohne weitere Angaben entsteht zunächst ein Raster mit nur einer Spalte, in dem die Kinder untereinanderstehen. Erst `grid-template-columns` erzeugt mehrere Spalten."]},{"titel":"Zwei gleich breite Spalten","text":"grid-template-columns bestimmt die Spalten. Mit 1fr 1fr entstehen zwei gleich breite Spalten. fr bezeichnet einen Anteil des freien Platzes. Das Raster passt sich an die Containerbreite an. Die beiden Spalten erhalten jeweils die Hälfte des freien Raums.","code":"main { grid-template-columns: 1fr 1fr; }","erklaerung":"Zwei gleiche Anteile ergeben zwei Spalten.","tiefer":["Die Einheit `fr` (fraction, Bruchteil) verteilt den freien Platz nach Anteilen. `1fr 2fr` ergibt eine schmale und eine doppelt so breite Spalte. Du kannst fr auch mit festen Werten mischen, etwa `200px 1fr` für eine feste Seitenleiste und einen flexiblen Hauptbereich.","Für viele gleiche Spalten gibt es `repeat`: `repeat(3, 1fr)` statt `1fr 1fr 1fr`. Besonders praktisch ist `repeat(auto-fit, minmax(200px, 1fr))`: Der Browser setzt so viele Spalten, wie mit mindestens 200 Pixeln Breite hineinpassen – ganz ohne Media Query."]},{"titel":"Zwischenräume mit gap","text":"Mit gap schaffst du Luft zwischen den Feldern. Das gilt für Zeilen und Spalten. Einzelne Karten benötigen keine eigenen Ränder. Das Raster bleibt dadurch regelmäßig. Ein Abstand zwischen den Fächern verbessert die Übersicht.","code":"main { gap: 16px; }","erklaerung":"Zwischen den Karten liegen sechzehn Pixel.","tiefer":["`gap` legt die Abstände zwischen den Rasterzellen fest, aber nicht am äußeren Rand. Mit `row-gap` und `column-gap` steuerst du Zeilen- und Spaltenabstand getrennt. Für einen Abstand zum Seitenrand setzt du padding auf den Container.","Einzelne Elemente können sich über mehrere Zellen erstrecken: `grid-column: span 2` macht eine Karte doppelt so breit. Mit `grid-template-areas` lassen sich Bereiche sogar mit Namen wie „kopf“, „menue“ und „inhalt“ beschreiben, was große Layouts sehr übersichtlich macht."]},{"titel":"Einspaltige Handyansicht","text":"Auf einem schmalen Handy kann eine Spalte besser sein. Ein Raster mit nur 1fr stapelt die Karten. Du kannst die Spalten später per Media Query ändern. Prüfe die Lesbarkeit bei 320 Pixeln. Einspaltige Karten sind auf kleinen Handys leichter zu lesen.","code":"main { grid-template-columns: 1fr; }","erklaerung":"Alle Karten stehen untereinander.","tiefer":["Diese Vorgehensweise heißt Mobile First: Man gestaltet zuerst die einspaltige Handyansicht und ergänzt für größere Bildschirme weitere Spalten. Inzwischen nutzen weltweit mehr Menschen das Internet mit dem Handy als mit dem Computer, deshalb ist diese Reihenfolge sinnvoll.","Die Reihenfolge im HTML bestimmt auch die Reihenfolge beim Vorlesen und bei der Tastaturbedienung. Grid kann Elemente zwar optisch umsortieren, doch die logische Reihenfolge sollte dabei sinnvoll bleiben, sonst springt der Fokus für Tastaturnutzer verwirrend über die Seite."]}],"beispiel":{"html":"<main><article>A</article><article>B</article></main>","css":"","js":""},"aufgabe":{"text":"Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.","pruefungen":[{"beschreibung":"Die passende HTML-Struktur ist vorhanden.","test":"p2-grid-html"},{"beschreibung":"Die passende Gestaltung oder Beschriftung ist vorhanden.","test":"p2-grid-css"}],"tipp":"Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.","loesung":{"html":"<main><article>A</article><article>B</article></main>","css":"main {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n}","js":""}},"fehler":[{"titel":"grid-template-columns ohne display: grid","text":"Wenn die Karten nicht in Spalten stehen, ist nur `grid-template-columns` gesetzt. Ergänze am Eltern-Element `main { display: grid; grid-template-columns: 1fr 1fr; }`."},{"titel":"Feste Spalten zu breit für das Handy","text":"Wenn zwei feste Spalten auf dem Handy über den Rand gehen, ist das Raster zu breit. Beginne mit `main { grid-template-columns: 1fr; }` und schalte zwei Spalten erst für größere Ansichten ein."}],"quiz":[{"frage":"Welche Eigenschaft legt Grid-Spalten fest?","antworten":["grid-row","grid-template-columns","flex-wrap"],"richtig":1,"erklaerung":"Bei „Welche Eigenschaft legt Grid-Spalten fest?“ ist „grid-template-columns“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was bedeutet 1fr 1fr?","antworten":["Zwei gleiche Spalten","Zwei feste Pixel","Eine einzige Zeile"],"richtig":0,"erklaerung":"Für diese Aufgabe passt „Zwei gleiche Spalten“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.","begruendungen":["Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Welche Regel aktiviert Grid?","antworten":["display: block","position: grid","display: grid"],"richtig":2,"erklaerung":"Die Auswahl „display: grid“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe."]}],"merke":["Grid teilt den Platz in definierte Spalten und Zeilen.","Eine einzelne `1fr`-Spalte ist für kleine Ansichten oft leichter lesbar."]},{"id":"p2-5","title":"Responsive mit Media Queries","minutes":25,"ziel":"Gestaltung an schmale Bildschirme anpassen.","schritte":[{"titel":"Bildschirmbreite abfragen","text":"Ein Stadtplan wird auf dem Handy anders gefaltet als auf dem Tisch. Eine Webseite braucht ebenfalls verschiedene Anordnungen. Eine Media Query prüft die Bildschirmbreite. Danach gelten passende CSS-Regeln. Die Bildschirmbreite kann sich beim Drehen eines Handys verändern.","code":"@media (max-width: 600px) { body { font-size: 16px; } }","erklaerung":"Die Regel gilt bis zu einer Breite von 600 Pixeln.","tiefer":["Eine Media Query ist eine Bedingung im CSS: `@media (min-width: 700px) { ... }` – die Regeln in den Klammern gelten nur, wenn das Fenster mindestens 700 Pixel breit ist. Neben der Breite kann man auch die Ausrichtung, den Druck oder die bevorzugte Farbdarstellung abfragen, etwa `prefers-color-scheme: dark`.","Damit Media Queries auf dem Handy richtig funktionieren, braucht jede Seite im Kopfbereich die Zeile `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">`. Ohne sie tut das Handy so, als wäre es ein breiter Computerbildschirm, und verkleinert alles."]},{"titel":"Bilder flexibel halten","text":"Beginne mit einer gut lesbaren Handyansicht. Verwende Breiten in Prozent statt überall feste Pixel. Große Bilder dürfen nicht aus dem Bildschirm ragen. max-width: 100% hilft dabei. Ein Foto soll nicht über die sichtbare Seitenkante hinauslaufen.","code":"img { max-width: 100%; }","erklaerung":"Das Bild überschreitet seinen verfügbaren Platz nicht.","tiefer":["Prozentangaben beziehen sich auf die Breite des umgebenden Elements. Dazu gibt es weitere relative Einheiten: `rem` richtet sich nach der Grundschriftgröße, `vw` nach der Fensterbreite. Relative Einheiten passen sich an, wenn Menschen in den Einstellungen größere Schrift wählen.","`max-width: 100%` erlaubt einem Bild, kleiner zu werden, aber nie größer als sein Platz. Ergänze `height: auto`, damit es nicht verzerrt wird. Für scharfe Bilder auf hochauflösenden Displays kann der Browser mit `srcset` automatisch eine passende Bildgröße auswählen."]},{"titel":"Spalten ab 700 Pixeln","text":"Für größere Bildschirme kannst du zusätzliche Spalten aktivieren. Eine Media Query mit min-width gilt ab einer bestimmten Breite. Die Grundgestaltung bleibt erhalten. Nur die Unterschiede werden überschrieben. Die zweite Spalte ist nur auf ausreichend breiten Geräten sinnvoll.","code":"@media (min-width: 700px) { main { grid-template-columns: 1fr 1fr; } }","erklaerung":"Ab 700 Pixeln gibt es zwei Spalten.","tiefer":["Bei Mobile First stehen die Grundregeln für das Handy ohne Media Query oben, und `min-width`-Abfragen fügen für größere Bildschirme Änderungen hinzu. Die Grenzwerte nennt man Breakpoints. Wähle sie nach deinem Inhalt – dort, wo das Layout unschön wird –, nicht nach einzelnen Gerätemodellen.","Media Queries erhöhen die Spezifität nicht. Darum müssen sie im Stylesheet nach den Grundregeln stehen, sonst überschreiben die Grundregeln sie wieder. Neuere Container Queries reagieren sogar auf die Breite eines Elternelements statt des ganzen Fensters."]},{"titel":"320-Pixel-Ansicht kontrollieren","text":"Teste nicht nur auf deinem eigenen Handy. Bei 320 Pixeln sind lange Wörter besonders kritisch. Bei 390 Pixeln sollten Knöpfe gut erreichbar sein. Am PC darf die Textzeile nicht endlos breit werden. Teste lange Vereinsnamen zusätzlich mit vergrößerter Schrift.","code":"article { overflow-wrap: anywhere; }","erklaerung":"Lange Wörter können umgebrochen werden.","tiefer":["320 Pixel entsprechen der Breite kleiner Smartphones und sind ein verbreiteter Mindestwert beim Testen. In den Entwicklerwerkzeugen gibt es einen Gerätemodus, mit dem du beliebige Breiten ausprobieren kannst. Auf echten Geräten zu testen, bleibt trotzdem wichtig, etwa wegen der Bildschirmtastatur.","Lange Wörter, wie sie im Deutschen häufig sind, können schmale Spalten sprengen. `overflow-wrap: anywhere` erlaubt dem Browser, notfalls mitten im Wort umzubrechen, und `hyphens: auto` trennt mit Bindestrich, wenn die Seite `lang=\"de\"` angibt. Für gut lesbare Textzeilen auf großen Bildschirmen begrenzt man die Breite auf etwa 60 bis 75 Zeichen."]}],"beispiel":{"html":"<main><article>Unsere Angebote</article></main>","css":"","js":""},"aufgabe":{"text":"Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.","pruefungen":[{"beschreibung":"Die passende HTML-Struktur ist vorhanden.","test":"p2-media-html"},{"beschreibung":"Die passende Gestaltung oder Beschriftung ist vorhanden.","test":"p2-media-css"}],"tipp":"Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.","loesung":{"html":"<main><article>Unsere Angebote</article></main>","css":"main { display: grid; grid-template-columns: 1fr; }\n@media (min-width: 700px) {\n  main { grid-template-columns: 1fr 1fr; }\n}","js":""}},"fehler":[{"titel":"min-width und max-width verwechselt","text":"Wenn die Handyregel auf einem großen Monitor statt auf einem kleinen Bildschirm wirkt, wurden `min-width` und `max-width` vertauscht. Für höchstens 600 Pixel nutze `@media (max-width: 600px) { ... }`."},{"titel":"Feste Breiten erzeugen horizontales Scrollen","text":"Wenn ein breites Bild seitliches Scrollen verursacht, ist seine Breite nicht begrenzt. Ergänze `img { max-width: 100%; height: auto; }`, damit es in den verfügbaren Platz passt."}],"quiz":[{"frage":"Welche Media Query gilt bei 500 Pixeln?","antworten":["@media (min-width: 900px)","@media (max-width: 600px)","@media print"],"richtig":1,"erklaerung":"Bei „Welche Media Query gilt bei 500 Pixeln?“ ist „@media (max-width: 600px)“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was verhindert zu breite Bilder?","antworten":["max-width: 100%","width: 1200px","white-space: nowrap"],"richtig":0,"erklaerung":"Für diese Aufgabe passt „max-width: 100%“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.","begruendungen":["Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was bedeutet mobile first?","antworten":["Nur für Handys entwickeln","Alle Geräte gleich darstellen","Zuerst die schmale Ansicht gestalten"],"richtig":2,"erklaerung":"Die Auswahl „Zuerst die schmale Ansicht gestalten“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe."]}],"merke":["`max-width` begrenzt Regeln nach oben, `min-width` aktiviert sie ab einer Breite.","Responsive Seiten bleiben auch bei 320 Pixeln ohne waagerechtes Scrollen nutzbar."]},{"id":"p2-6","title":"Formulare richtig bauen","minutes":25,"ziel":"Beschriftungen, Eingabetypen und Prüfung einsetzen.","schritte":[{"titel":"Beschriftung und Eingabe koppeln","text":"Ein Papierformular hat zu jedem Feld eine Überschrift. Im Web übernimmt label diese Aufgabe. Die Beschriftung sagt, was eingegeben werden soll. Mit for und id verbindest du beide Teile. Eine klare Beschriftung hilft auch Menschen mit Vorleseprogramm.","code":"<label for=\"mail\">E-Mail</label>\n<input id=\"mail\" type=\"email\">","erklaerung":"for und id haben denselben Wert.","tiefer":["Ein mit `for` und `id` verknüpftes label hat zwei Vorteile: Vorleseprogramme lesen die Beschriftung vor, sobald das Feld den Fokus bekommt, und ein Klick auf die Beschriftung setzt den Cursor ins Feld. Bei kleinen Kontrollkästchen vergrößert das die Klickfläche deutlich.","Alternativ kannst du das Eingabefeld direkt in das label schreiben: `<label>Name <input name=\"name\"></label>`. Ein Platzhaltertext (`placeholder`) ersetzt kein label, weil er beim Tippen verschwindet und oft zu blass ist. Das Attribut `name` bestimmt, unter welchem Namen der Wert beim Absenden übertragen wird."]},{"titel":"Eingabetypen bewusst wählen","text":"Ein Eingabetyp hilft dem Browser bei der Bedienung. type=\"email\" zeigt auf Handys oft eine passende Tastatur. type=\"tel\" eignet sich für Telefonnummern. Ein guter Typ macht das Formular leichter. Der Eingabetyp kann auf dem Handy die passende Tastatur öffnen.","code":"<input type=\"tel\" id=\"telefon\">","erklaerung":"Der Browser erkennt ein Feld für Telefonnummern.","tiefer":["HTML kennt viele Eingabetypen: `email`, `tel`, `number`, `date`, `url`, `password`, `checkbox`, `radio` und weitere. Der Browser liefert dazu passende Bedienhilfen, etwa einen Kalender bei `date`. Unbekannte Typen behandelt ein alter Browser einfach wie ein normales Textfeld.","Mit `autocomplete` hilfst du dem Browser beim automatischen Ausfüllen, zum Beispiel `autocomplete=\"email\"` oder `\"street-address\"`. Das spart Menschen viel Tipparbeit. `inputmode=\"numeric\"` zeigt auf dem Handy die Zifferntastatur, ohne die Prüfung von `type=\"number\"` zu erzwingen."]},{"titel":"Pflichtfelder kennzeichnen","text":"required kennzeichnet ein Pflichtfeld. Der Browser kann vor dem Absenden auf fehlende Angaben hinweisen. Das ersetzt keine sichere Prüfung auf einem Server. Für eine reine Übung reicht die Browserprüfung. Ein Pflichtfeld braucht zusätzlich eine verständliche Fehlermeldung.","code":"<input id=\"mail\" type=\"email\" required>","erklaerung":"Das Feld muss ausgefüllt werden und eine E-Mail-Form haben.","tiefer":["Weitere Prüfattribute sind `minlength`, `maxlength`, `min`, `max` und `pattern` mit einem regulären Ausdruck. Mit der CSS-Pseudoklasse `:invalid` kannst du ungültige Felder gestalten. Die eingebauten Meldungen formuliert der Browser in der Sprache des Systems.","Browserprüfungen lassen sich leicht umgehen, etwa über die Entwicklerwerkzeuge oder mit eigenen Anfragen. Ein Server muss deshalb jede Eingabe noch einmal selbst prüfen. Dieser Grundsatz – dem Client nie vertrauen – gehört zu den wichtigsten Regeln der Websicherheit."]},{"titel":"Senden-Knopf festlegen","text":"Ein Button mit type=\"submit\" sendet das Formular ab. Ein Button mit type=\"button\" löst das nicht automatisch aus. Wähle den Typ bewusst. Teste das Formular auch mit der Tastatur. Kontrolliere, ob die Eingabe auch ohne Maus abgeschickt werden kann.","code":"<button type=\"submit\">Absenden</button>","erklaerung":"Der Knopf ist als Senden-Knopf markiert.","tiefer":["Ein `button` innerhalb eines Formulars ist ohne Angabe automatisch ein Absende-Knopf. Darum lösen Knöpfe zum Beispiel für „Passwort anzeigen“ versehentlich das Absenden aus, wenn `type=\"button\"` fehlt. Gib den Typ deshalb immer ausdrücklich an.","Drückt man in einem Textfeld Enter, schickt der Browser das Formular ebenfalls ab. Mit JavaScript fängt man das Ereignis `submit` am Formular ab, nicht den Klick auf den Knopf – so funktionieren Maus, Tastatur und Enter gleichermaßen. `event.preventDefault()` verhindert dabei das Neuladen der Seite."]}],"beispiel":{"html":"<form><input placeholder=\"E-Mail\"><button>Senden</button></form>","css":"","js":""},"aufgabe":{"text":"Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.","pruefungen":[{"beschreibung":"Die passende HTML-Struktur ist vorhanden.","test":"p2-form-html"},{"beschreibung":"Die passende Gestaltung oder Beschriftung ist vorhanden.","test":"p2-form-css"}],"tipp":"Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.","loesung":{"html":"<form>\n  <label for=\"mail\">E-Mail</label>\n  <input id=\"mail\" type=\"email\" required>\n  <button type=\"submit\">Senden</button>\n</form>","css":"","js":""}},"fehler":[{"titel":"label ohne passende id","text":"Wenn ein Klick auf die Beschriftung das Eingabefeld nicht aktiviert, passen `for` und `id` nicht zusammen. Korrekt: `<label for=\"mail\">E-Mail</label><input id=\"mail\" type=\"email\">`."},{"titel":"required mit sicherer Serverprüfung verwechselt","text":"Wenn ein leeres Pflichtfeld ohne Hinweis gesendet werden kann, fehlt möglicherweise `required`. Nutze `<input id=\"mail\" type=\"email\" required>`; prüfe sensible Daten zusätzlich auf einem Server."}],"quiz":[{"frage":"Was verbindet label mit input?","antworten":["class und style","for und id","name und value"],"richtig":1,"erklaerung":"Bei „Was verbindet label mit input?“ ist „for und id“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Welcher Typ passt zur E-Mail-Adresse?","antworten":["email","date","color"],"richtig":0,"erklaerung":"Für diese Aufgabe passt „email“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.","begruendungen":["Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was kennzeichnet ein Pflichtfeld?","antworten":["placeholder","readonly","required"],"richtig":2,"erklaerung":"Die Auswahl „required“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe."]}],"merke":["`label for` und `input id` müssen genau übereinstimmen.","`required` hilft bei der Browserprüfung, ersetzt aber keine serverseitige Validierung."]},{"id":"p2-7","title":"Barrierefreiheit im Alltag","minutes":25,"ziel":"Eine Webseite mit Tastatur und Vorleseprogramm bedienen.","schritte":[{"titel":"Echte Schaltflächen einsetzen","text":"Ein Gebäude braucht einen Eingang für verschiedene Menschen. Eine Webseite soll ebenso zugänglich sein. Verwende dafür echte HTML-Elemente. Ein button ist besser als ein klickbarer Absatz. Ein echter Knopf besitzt bereits eine passende Tastaturfunktion.","code":"<button type=\"button\">Menü öffnen</button>","erklaerung":"Der Browser erkennt einen bedienbaren Knopf.","tiefer":["Ein echter `button` ist automatisch mit Tab erreichbar, lässt sich mit Enter und Leertaste auslösen und wird von Vorleseprogrammen als Schaltfläche angesagt. Ein klickbarer Absatz kann nichts davon. Wer dieses Verhalten selbst nachbauen will, braucht viel zusätzlichen Code und vergisst leicht etwas.","Barrierefreiheit betrifft viele Menschen: Blinde und sehbehinderte Menschen, Menschen mit motorischen Einschränkungen, ältere Menschen, aber auch jeden mit gebrochenem Arm oder grellem Sonnenlicht auf dem Display. International gelten dafür die Richtlinien WCAG; in der EU verpflichtet der European Accessibility Act seit 2025 viele Unternehmen zu barrierefreien Angeboten."]},{"titel":"Überschriften sinnvoll ordnen","text":"Überschriften geben dem Inhalt eine klare Ordnung. Beginne mit einer passenden h1. Darunter folgen h2 für größere Abschnitte. Vorleseprogramme können so leichter navigieren. Die Überschriftenstruktur ist wie das Inhaltsverzeichnis eines Buches.","code":"<h1>Verein</h1>\n<h2>Kontakt</h2>","erklaerung":"Die zweite Überschrift gehört zum Abschnitt Kontakt.","tiefer":["Vorleseprogramme wie NVDA, JAWS oder VoiceOver können eine Liste aller Überschriften anzeigen und direkt zu ihnen springen. Viele blinde Menschen erkunden eine Seite genau so. Überspringst du Ebenen, etwa von h1 direkt zu h4, wirkt die Gliederung lückenhaft.","Wähle Überschriften nach ihrer Bedeutung, nicht nach ihrer Größe – die Größe stellst du mit CSS ein. Ergänzend helfen Bereichselemente wie `header`, `nav`, `main` und `footer`, die Vorleseprogramme als Landmarken anbieten. So findet man schnell zum Hauptinhalt."]},{"titel":"Alternativtexte für Bilder","text":"Ein Bild braucht einen sinnvollen Alternativtext. Der alt-Text beschreibt wichtige Bildinformationen. Ein rein dekoratives Bild darf alt=\"\" haben. Schreibe nicht nur das Wort Bild. Ein Alternativtext soll den wichtigen Bildinhalt knapp benennen.","code":"<img src=\"logo.svg\" alt=\"Logo des Vereins\">","erklaerung":"Der Alternativtext nennt den Inhalt des Logos.","tiefer":["Ein guter Alternativtext beschreibt, was das Bild an dieser Stelle aussagt. Beim Foto eines Vereinsfests reicht „Kinder spielen Fußball auf dem Vereinsplatz“. Ist das Bild ein Link, beschreibt der Text das Ziel, etwa „Zur Startseite“. Bildschirmleser sagen ohnehin „Bild“ an.","Fehlt das alt-Attribut ganz, lesen manche Programme den Dateinamen vor, etwa „IMG_4711.jpg“. Bei rein dekorativen Bildern sorgt `alt=\"\"` dafür, dass sie übersprungen werden. Diagramme mit vielen Informationen brauchen zusätzlich eine Beschreibung im Text."]},{"titel":"Fehler auch als Text melden","text":"Farbe allein reicht nicht für Fehlermeldungen. Zeige zusätzlich einen verständlichen Text. Achte auf lesbaren Kontrast. Prüfe, ob du die Seite mit Tab und Enter bedienen kannst. Eine Meldung darf nicht allein durch ihre Farbe verständlich sein.","code":"<p role=\"status\">Bitte E-Mail prüfen.</p>","erklaerung":"Der Status kann auch vorgelesen werden.","tiefer":["Etwa jeder zwölfte Mann hat eine Rot-Grün-Sehschwäche. Ein rot markiertes Feld allein ist für ihn kaum von einem grünen zu unterscheiden. Darum gehört zu jeder Fehlermeldung ein Text, der sagt, was falsch ist und wie man es behebt, und gerne ein Symbol.","Für normalen Text verlangen die WCAG ein Kontrastverhältnis von mindestens 4,5 zu 1 zwischen Schrift und Hintergrund. Kostenlose Kontrastprüfer zeigen dir den Wert. Achte auch auf einen sichtbaren Fokusrahmen, damit Tastaturnutzer jederzeit sehen, wo sie sich befinden."]}],"beispiel":{"html":"<h1>Kontakt</h1><img src=\"logo.svg\">","css":"","js":""},"aufgabe":{"text":"Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.","pruefungen":[{"beschreibung":"Die passende HTML-Struktur ist vorhanden.","test":"p2-alt-html"},{"beschreibung":"Die passende Gestaltung oder Beschriftung ist vorhanden.","test":"p2-alt-css"}],"tipp":"Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.","loesung":{"html":"<h1>Kontakt</h1>\n<img src=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg'%3E%3Ccircle cx='20' cy='20' r='18' fill='green'/%3E%3C/svg%3E\" alt=\"Grünes Vereinslogo\">","css":"","js":""}},"fehler":[{"titel":"Klickbarer div statt echter Schaltfläche","text":"Wenn ein Element per Tab-Taste nicht erreichbar ist, wurde eventuell ein klickbarer `div` verwendet. Setze für Aktionen `<button type=\"button\">Menü öffnen</button>` ein."},{"titel":"Bild ohne passenden Alternativtext","text":"Wenn ein Vorleseprogramm das wichtige Logo nicht beschreibt, fehlt der Alternativtext. Ergänze `<img src=\"logo.svg\" alt=\"Logo des Vereins\">`; dekorative Bilder erhalten `alt=\"\"`."}],"quiz":[{"frage":"Welches Element ist ein echter Knopf?","antworten":["<button>OK</button>","<span>OK</span>","<div>OK</div>"],"richtig":0,"erklaerung":"Bei „Welches Element ist ein echter Knopf?“ ist „<button>OK</button>“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.","begruendungen":["Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was gehört zu einem wichtigen Bild?","antworten":["Nur eine Farbe","Ein sinnvoller alt-Text","Ein versteckter Link"],"richtig":1,"erklaerung":"Für diese Aufgabe passt „Ein sinnvoller alt-Text“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was hilft bei einer Fehlermeldung?","antworten":["Nur rote Farbe","Nur ein Symbol","Text zusätzlich zur Farbe"],"richtig":2,"erklaerung":"Die Auswahl „Text zusätzlich zur Farbe“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe."]}],"merke":["Semantische Elemente wie `button` unterstützen Tastatur und Vorleseprogramme.","Wichtige Bilder brauchen einen passenden Alternativtext, nicht bloß eine Farbe."]},{"id":"p2-8","title":"Projekt: Vereinsseite","minutes":25,"ziel":"Eine zugängliche responsive Vereinsseite erstellen.","schritte":[{"titel":"Vereinsnamen und Angebot zeigen","text":"Ein Verein möchte neue Mitglieder begrüßen. Die Startseite braucht einen Namen und eine kurze Beschreibung. Verwende dafür eine h1 und einen Absatz. Besucher sollen sofort verstehen, worum es geht. Eine Vereinsseite ist die digitale Eingangstür für neue Mitglieder.","code":"<h1>Verein Miteinander</h1>\n<p>Wir treffen uns jeden Samstag.</p>","erklaerung":"Die Überschrift nennt den Verein und der Absatz die Aktivität.","tiefer":["Planen hilft: Lege vor dem Programmieren fest, welche Bereiche die Seite braucht, zum Beispiel Kopf mit Namen, Angebote, Termine und Kontakt. Eine einfache Skizze auf Papier, Wireframe genannt, zeigt die Anordnung ohne Farben und Details.","Der Inhalt von `title` im Kopfbereich erscheint im Browser-Tab und in Suchergebnissen, die `meta`-Beschreibung oft als Vorschautext. Beide sollten kurz sagen, worum es geht. Eine klare h1 mit dem Vereinsnamen hilft Menschen und Suchmaschinen gleichermaßen."]},{"titel":"Kontaktziel verlinken","text":"Eine Navigation führt zu Angeboten und Kontakt. Verwende dafür echte Links mit sinnvollen Namen. Die Ziele müssen im Dokument existieren. So bleiben die Wege verständlich. Der Kontaktlink sollte einen klaren Namen tragen.","code":"<a href=\"#kontakt\">Zum Kontakt</a>","erklaerung":"Der Link springt zum Abschnitt mit id kontakt.","tiefer":["Ein Link mit `#kontakt` springt zum Element mit `id=\"kontakt\"` auf derselben Seite. Mit der CSS-Regel `html { scroll-behavior: smooth; }` scrollt der Browser sanft dorthin. Für Menschen, die Bewegungen schlecht vertragen, schaltet man das mit `prefers-reduced-motion` wieder ab.","Linktexte sollten auch ohne Umgebung verständlich sein. „Hier klicken“ sagt in einer Linkliste eines Vorleseprogramms nichts aus, „Zum Kontaktformular“ dagegen schon. Links zu anderen Seiten öffnen sich am besten im selben Tab, damit die Zurück-Taste wie erwartet funktioniert."]},{"titel":"Angebote als Raster gestalten","text":"Gestalte Karten für die Angebote. CSS Grid sorgt auf großen Bildschirmen für Spalten. Auf dem Handy bleiben die Karten untereinander. Gib jeder Karte ausreichend Innenabstand. Ein Kartenraster trennt Angebote, ohne Informationen zu verstecken.","code":"main { display: grid; gap: 16px; }","erklaerung":"Das Raster trennt die Angebote sichtbar.","tiefer":["Jede Angebotskarte kann ein `article`-Element mit eigener Überschrift sein. Mit `repeat(auto-fit, minmax(240px, 1fr))` ordnet das Raster die Karten automatisch in so viele Spalten an, wie Platz ist. Gleich hohe Karten entstehen in Grid von selbst.","Bilder in Karten sollten ein festes Seitenverhältnis haben, damit das Raster ruhig wirkt: `aspect-ratio: 4 / 3` zusammen mit `object-fit: cover` schneidet Fotos passend zu, ohne sie zu verzerren. Mit `loading=\"lazy\"` lädt der Browser Bilder erst, wenn sie in die Nähe des sichtbaren Bereichs kommen."]},{"titel":"Tastatur und Handy prüfen","text":"Prüfe am Ende die Tastatur und das Handyformat. Eine Kontaktmöglichkeit muss klar erkennbar sein. Nutze gut lesbare Farben und Beschriftungen. Erst danach übergibst du die Seite an das Code-Studio. Probiere das Projekt mit Tastatur und schmaler Handyansicht aus.","code":"<section id=\"kontakt\"><h2>Kontakt</h2><p>Schreib uns!</p></section>","erklaerung":"Der Kontaktabschnitt ist das Ziel des Navigationslinks.","tiefer":["Ein vollständiger Abschlusstest umfasst: alle Links anklicken, die Seite nur mit Tab, Enter und Leertaste bedienen, Breiten von 320 Pixeln bis Desktop prüfen und die Kontraste kontrollieren. Das kostenlose Werkzeug Lighthouse in Chrome erstellt dazu automatisch einen Bericht über Barrierefreiheit und Ladezeit.","Automatische Prüfungen finden nur einen Teil der Probleme. Am aussagekräftigsten ist es, jemanden die Seite ausprobieren zu lassen, der sie noch nicht kennt. Beobachte dabei, wo die Person zögert – genau dort lohnt sich eine Verbesserung."]}],"beispiel":{"html":"<h1>Mein Verein</h1>","css":"","js":""},"aufgabe":{"text":"Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.","pruefungen":[{"beschreibung":"Die passende HTML-Struktur ist vorhanden.","test":"p2-project-html"},{"beschreibung":"Die passende Gestaltung oder Beschriftung ist vorhanden.","test":"p2-project-css"}],"tipp":"Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.","loesung":{"html":"<header>\n  <h1>Verein Miteinander</h1>\n  <nav><a href=\"#kontakt\">Kontakt</a></nav>\n</header>\n<main>\n  <article><h2>Unsere Angebote</h2><p>Wir helfen einander.</p></article>\n  <section id=\"kontakt\"><h2>Kontakt</h2><p>Schreib uns!</p></section>\n</main>","css":"main { display: grid; gap: 16px; }\n@media (min-width: 700px) {\n  main { grid-template-columns: 1fr 1fr; }\n}","js":""}},"fehler":[{"titel":"Linkziel #kontakt ohne passenden Abschnitt","text":"Wenn der Kontaktlink beim Anklicken nicht zum Abschnitt springt, fehlt die passende ID. Verbinde `<a href=\"#kontakt\">Kontakt</a>` mit `<section id=\"kontakt\">...</section>`."},{"titel":"Karten ohne Umbruch auf schmalem Bildschirm","text":"Wenn Angebotskarten auf einem kleinen Display nebeneinander gequetscht werden, fehlt die mobile Grundregel. Nutze `main { display: grid; grid-template-columns: 1fr; }` und ergänze größere Spalten erst per Media Query."}],"quiz":[{"frage":"Welcher Link springt zum Kontaktabschnitt?","antworten":["<a>Kontakt</a>","<a href=\"#kontakt\">Kontakt</a>","<p>Kontakt</p>"],"richtig":1,"erklaerung":"Bei „Welcher Link springt zum Kontaktabschnitt?“ ist „<a href=\"#kontakt\">Kontakt</a>“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]},{"frage":"Was gehört zu einer guten Startseite?","antworten":["Nur dekorative Bilder","Nur ein leeres Menü","Name und verständliche Beschreibung"],"richtig":2,"erklaerung":"Für diese Aufgabe passt „Name und verständliche Beschreibung“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.","begruendungen":["Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe passt zur beschriebenen Aufgabe."]},{"frage":"Was prüfst du vor der Veröffentlichung?","antworten":["Handyansicht und Tastatur","Nur die PC-Ansicht","Nur die Schriftfarbe"],"richtig":0,"erklaerung":"Die Auswahl „Handyansicht und Tastatur“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.","begruendungen":["Diese Angabe passt zur beschriebenen Aufgabe.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.","Diese Angabe erfüllt die beschriebene Aufgabe nicht."]}],"merke":["Ein Kontaktlink mit `#kontakt` braucht ein Ziel mit `id=\"kontakt\"`.","Prüfe das fertige Projekt mit Tastatur, Handybreite und verständlichen Texten."]}];
if(typeof module!=="undefined"&&module.exports)module.exports=root.SDAkademieKurse["webdesign"];
})(typeof window!=="undefined"?window:globalThis);
